{"command": "python3 << 'EOF'
from rdkit import Chem

smiles = "Cc1nc2ccc(-c3ccc([C@H](C)N4CC[C@](CC(C)(C)O)(c5ccccc5)OC4=O)cc3)cc2[nH]1"
mol = Chem.MolFromSmiles(smiles)

if mol:
    print("Valid SMILES")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Find the indole ring system
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 7 and atom.GetIsAromatic():
            print(f"Aromatic nitrogen at position {atom.GetIdx()}")
            for neighbor in atom.GetNeighbors():
                print(f"  Neighbor: {neighbor.GetSymbol()} at position {neighbor.GetIdx()}")

    # Look for the lactam carbonyl
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 6:
            for bond in atom.GetBonds():
                if bond.GetBondType() == Chem.BondType.DOUBLE and bond.GetOtherAtom(atom).GetAtomicNum() == 8:
                    print(f"Lactam carbonyl carbon at position {atom.GetIdx()}, connected to N at position {bond.GetOtherAtom(atom).GetIdx()}")
else:
    print("Invalid SMILES")
EOF
"}

